package com.gymflow.supplier;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/gyms/{gymId}/suppliers")public class SupplierController{private final SupplierService service;public SupplierController(SupplierService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public SupplierResponse create(@PathVariable UUID gymId,@Valid @RequestBody SupplierRequest r){return service.create(gymId,r);}@GetMapping public List<SupplierResponse> findAll(@PathVariable UUID gymId){return service.findAll(gymId);}}
